sigme______ = {"workspace_id": "9bc66a85-60a7-4fa2-bdf5-709a1aea217d", "company_id": "930226c1-3d64-481b-86e1-29eba3107a6e", "user_id": "c95adbbf-3b35-43d3-b46c-cfae2c80dde8", "label": "Get Rules", "description": "Fetched rules from strikeready_intel", "success": True, "timestamp": 1725537244.754833, "type": "info", "metadata": {"plan_id": "66d99bd585fcb6aa5ed25b70", "job_id": "66d99bd585fcb6aa5ed25b71", "task_id": "66d99bd585fcb6aa5ed25b72", "action": {"name": "get_rules", "integration": None, "source": {"id": "12e1991f-73c1-4a43-94fa-2b27cb5a0c39", "value": "strikeready_intel", "type": "integration"}}, "resource": {"id": "66d99bdabbabe54646c52328", "entity": "Intel", "type": "sigma", "value": "title: Fsutil Suspicious Invocation\\nid: add64136-62e5-48ea-807e-88638d02df1e\\nstatus: stable\\ndescription: |\\n  Detects suspicious parameters of fsutil (deleting USN journal, configuring it with small size, etc).\\n  Might be used by ransomwares during the attack (seen by NotPetya and others).\\nreferences:\\n    - https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/fsutil-usn\\n    - https://github.com/redcanaryco/atomic-red-team/blob/f339e7da7d05f6057fdfcdd3742bfcf365fee2a9/atomics/T1070/T1070.md\\n    - https://eqllib.readthedocs.io/en/latest/analytics/c91f422a-5214-4b17-8664-c5fcf115c0a2.html\\n    - https://github.com/albertzsigovits/malware-notes/blob/558898932c1579ff589290092a2c8febefc3a4c9/Ransomware/Lockbit.md\\n    - https://blog.cluster25.duskrise.com/2023/05/22/back-in-black-blackbyte-nt\\nauthor: Ecco, E.M. Anhaus, oscd.community\\ndate: 2019-09-26\\nmodified: 2023-09-09\\ntags:\\n    - attack.defense-evasion\\n    - attack.impact\\n    - attack.t1070\\n    - attack.t1485\\nlogsource:\\n    category: process_creation\\n    product: windows\\ndetection:\\n    selection_img:\\n        - Image|endswith: \'\\\\fsutil.exe\'\\n        - OriginalFileName: \'fsutil.exe\'\\n    selection_cli:\\n        CommandLine|contains:\\n            - \'deletejournal\'        # usn deletejournal ==> generally ransomware or attacker\\n            - \'createjournal\'        # usn createjournal ==> can modify config to set it to a tiny size\\n            - \'setZeroData\'          # file setZeroData  ==> empties a file with zeroes\\n    condition: all of selection_*\\nfalsepositives:\\n    - Admin activity\\n    - Scripts and administrative tools used in the monitored environment\\nlevel: high\\n", "rule": None, "tags": [], "custom_score": None, "analysis_state": None, "analysis": {}, "object": None, "ruleValidation": {"deployable": True, "confidence": "high", "validator": "strikeready_intel", "complexity": None, "validatorType": "source", "timestamp": "2024-09-05T11:54:02.026315"}, "strikes": [], "sigmaParsedData": {"id": "add64136-62e5-48ea-807e-88638d02df1e", "title": "Fsutil Suspicious Invocation", "status": "stable", "fpStatus": ["Admin activity", "Scripts and administrative tools used in the monitored environment"], "references": ["https://blog.cluster25.duskrise.com/2023/05/22/back-in-black-blackbyte-nt", "https://eqllib.readthedocs.io/en/latest/analytics/c91f422a-5214-4b17-8664-c5fcf115c0a2.html", "https://github.com/redcanaryco/atomic-red-team/blob/f339e7da7d05f6057fdfcdd3742bfcf365fee2a9/atomics/T1070/T1070.md", "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/fsutil-usn", "https://github.com/albertzsigovits/malware-notes/blob/558898932c1579ff589290092a2c8febefc3a4c9/Ransomware/Lockbit.md"], "author": ["Ecco", "E.M. Anhaus", "oscd.community"], "metaDescription": "Detects suspicious parameters of fsutil (deleting USN journal, configuring it with small size, etc).\\nMight be used by ransomwares during the attack (seen by NotPetya and others).\\n", "createdDate": "2019-09-26T00:00:00", "modifiedDate": "2023-09-09T00:00:00", "tags": ["attack.defense-evasion", "attack.impact", "attack.t1070", "attack.t1485"], "logsource": {"category": ["process_creation"], "product": "windows", "definition": None, "service": []}, "detection": {"eventsSituations": [{"name": "selection_img", "value": [{"name": "Image|endswith", "value": ["\\\\fsutil.exe"]}, {"name": "OriginalFileName", "value": ["fsutil.exe"]}]}, {"name": "selection_cli", "value": [{"name": "CommandLine|contains", "value": ["deletejournal", "createjournal", "setZeroData"]}]}], "condition": "all of selection_*"}, "eventId": [], "level": "high", "sourceRev": None, "fields": []}, "telemetry": [], "sourceScore": None, "category": "Block", "threat": [], "vulnerability": [], "threatActors": [], "malwares": [], "name": "Fsutil Suspicious Invocation", "source": {"id": "", "name": "strikeready_intel", "displayName": "Sigma strikeready_intel", "url": "", "confidence": "high", "type": "ThreatFeed", "time": "2024-09-05T11:54:02.026163"}, "artifacts": {"urls": [], "domains": [], "ipAddresses": [], "objects": {}}, "srid": "eed8c14ea759f79ee816d28ca2aadca144c632f6a6672e690f81b3e90fb8179c", "mitreTtp": [{"tacId": None, "tacName": None, "tech": [{"techId": "T1485", "techName": "Data Destruction", "subTech": []}]}, {"tacId": None, "tacName": None, "tech": [{"techId": "T1070", "techName": "Indicator Removal", "subTech": []}]}], "ransoms": [], "lastUpdated": "2024-09-05T11:54:02.026526", "srScore": None, "internalTags": [], "relatedRuleIds": [], "tools": [], "hash": "eed8c14ea759f79ee816d28ca2aadca144c632f6a6672e690f81b3e90fb8179c", "tlp": "white"}}}

